  ('waste-management-and-circular-economy', 'Battery Recycling Industry', 'battery-recycling-industry', 'Li-ion, lead-acid battery recycling, cobalt and lithium recovery.', 25),
  ('waste-management-and-circular-economy', 'Extended Producer Responsibility Industry', 'extended-producer-responsibility-industry', 'EPR compliance, take-back programs, PRO platform services.', 26)
) AS v(sector_slug, name, slug, description, position)
JOIN desks d ON d.slug = v.sector_slug
ON CONFLICT (desk_id, slug) DO UPDATE SET
  name = EXCLUDED.name, description = EXCLUDED.description,
  position = EXCLUDED.position, updated_at = now();

COMMIT;
